-- Entrega 2026-11-27.3 (preparada el 27/11/2026) sobre la revisión 2026-11-27.2 (38ee1fa9-aadd-6c0a-b1e7-d2a4f006b6ca). Ciclo pedido y autorizado por el responsable del proyecto.
-- Disponibilidad por país de las 40 ofertas; sin altas ni retiradas. 73 plataformas y 40 ofertas (24/13/3).
-- Generado por rwadar-app/data/verificaciones/2026-11-27.3-v2/preparar-entrega.mjs; revisar antes de aplicar.
-- Generado localmente; revisar antes de cualquier aplicación remota.
-- Este aplicador importa y aprueba al final, únicamente si pasan todas las guardas.
begin isolation level serializable;
do $guarda$
declare actual uuid; retirada boolean;
begin
  select revision_id into actual from rwadar_catalogo.publicacion_v2 where unica for update;
  if actual is null or actual not in ('38ee1fa9-aadd-6c0a-b1e7-d2a4f006b6ca'::uuid, 'aa79f049-ae03-c031-83f4-e159a90ca05e'::uuid) then
    raise exception 'Publicación distinta de la revisión anterior prevista: %. No aplicar este lote.', actual;
  end if;
  if actual = '38ee1fa9-aadd-6c0a-b1e7-d2a4f006b6ca'::uuid and not exists (select 1 from rwadar_catalogo.revisiones where id = '38ee1fa9-aadd-6c0a-b1e7-d2a4f006b6ca'::uuid
    and contenido_sha256 = '38ee1fa9aadd6c0ab1e7d2a4f006b6ca5bcf2eda35a1c7180f8ddad9a690494a' and estado = 'aprobada') then
    raise exception 'La revisión publicada no tiene la identidad prevista o no está aprobada. No aplicar este lote.';
  end if;
  select retirado into retirada from public.catalogo_publicacion where unica for update;
  if retirada is distinct from false then
    raise exception 'Catálogo retirado o control ausente: este lote no autoriza reactivarlo.';
  end if;
  if current_date < date '2026-11-27' then raise exception 'Revisión futura'; end if;
  if current_date > date '2026-12-03' then
    raise exception 'Lote caducado: sus fichas valían hasta el 03/12/2026. No aplicar este lote.';
  end if;
  if exists (select 1 from rwadar_catalogo.revisiones where id = 'aa79f049-ae03-c031-83f4-e159a90ca05e'::uuid
    and (contenido_sha256 <> 'aa79f049ae03c03183f4e159a90ca05ed3245bd3dec6a12f43b4ad0f00cae7eb' or estado = 'retirada')) then
    raise exception 'La revisión destino existe con otra identidad o está retirada';
  end if;
end $guarda$;
do $publico_guarda$
begin
  if (select count(*) from public.plataformas where estado = 'en_radar') <> 73
    or (select count(*) from public.plataformas where estado = 'descartada') <> 5 then
    raise exception 'El radar no tiene 73 plataformas y 5 descartadas: no aplicar.';
  end if;
end $publico_guarda$;

do $aprobar$
declare v uuid := 'aa79f049-ae03-c031-83f4-e159a90ca05e';
begin
  if (select count(*) from rwadar_catalogo.plataformas where revision_id = v) <> 73
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v) <> 40
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'principales') <> 24
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'secundario') <> 13
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'en_camino') <> 3
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and documentacion ? 'disponibilidad') <> 40 then
    raise exception 'Catálogo incompleto: se conserva el lote anterior';
  end if;
  update rwadar_catalogo.revisiones set estado = 'aprobada', aprobada_el = now(),
    aprobada_referencia = 'Entrega 2026-11-27.3: las fichas de la 2026-11-27.2 con su disponibilidad por país, comprobada en la fuente oficial de cada oferta el 27/11/2026.'
    where id = v and estado = 'borrador';
  if not exists (select 1 from rwadar_catalogo.revision_publicable_v2 where id = v) then
    raise exception 'Entrega no publicable: se deshace la transacción completa';
  end if;
  if (select revision_id from rwadar_catalogo.publicacion_v2 where unica) is distinct from v then
    raise exception 'La revisión nueva no quedó publicada: se deshace la transacción completa';
  end if;
end $aprobar$;
commit;
